/* The hosted server owns account credentials and sessions; standalone opens it. */
(()=>{'use strict';let user=null,mode='login';const hosted=Boolean(window.KPOnlineAccountsHosted);const tr=s=>window.KPLanguage?.translate(s)||((document.documentElement.lang==='mr'?{'Account':'खाते','Sign in':'प्रवेश करा','Create account':'खाते तयार करा','Email':'ईमेल','Password':'संकेतशब्द','Name':'नाव','Close':'बंद करा','Sign out':'बाहेर पडा','Account server address':'खात्याच्या सर्व्हरचा पत्ता','Open online accounts':'ऑनलाइन खाते उघडा'}[s]:null)||s);
function el(tag,text){const n=document.createElement(tag);if(text){const label=tr(text);n.textContent=tag==='button'&&label!==text?label+' · '+text:label;}return n;}
async function api(path,data){const r=await fetch('/auth/'+path,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json','X-KP-Account':'1'}:{},body:data?JSON.stringify(data):undefined,credentials:'same-origin',cache:'no-store'}),d=await r.json();if(!r.ok)throw Error(d.error||'Account connection failed.');return d;}
function open(){document.getElementById('kp-account-dialog')?.remove();const dialog=el('dialog');dialog.id='kp-account-dialog';dialog.className='kp-account-dialog';const heading=el('h2','Account'),form=el('form'),status=el('p');status.setAttribute('role','status');dialog.append(heading,form,status);const close=el('button','Close');close.type='button';close.addEventListener('click',()=>dialog.close());dialog.append(close);document.body.append(dialog);dialog.addEventListener('close',()=>dialog.remove());
if(!hosted){form.append(el('p','Online accounts require your hosted software address.'));const label=el('label','Account server address'),address=el('input');address.type='url';address.required=true;address.placeholder='https://';try{address.value=localStorage.getItem('kpAccountServerV1')||'';}catch(_){}label.append(address);form.append(label);const submit=el('button','Open online accounts');form.append(submit);form.addEventListener('submit',e=>{e.preventDefault();try{const url=new URL(address.value);if(url.protocol!=='https:'&&!(['localhost','127.0.0.1'].includes(url.hostname)&&url.protocol==='http:'))throw Error('Use the HTTPS address of your account server.');url.pathname='/';url.search='';url.hash='account';try{localStorage.setItem('kpAccountServerV1',url.origin);}catch(_){}window.open(url.href,'_blank','noopener');dialog.close();}catch(err){status.textContent=tr(err.message);}});}
else if(user){const info=el('p');info.textContent=user.name+' · '+user.email;form.append(info);const logout=el('button','Sign out');logout.type='button';logout.addEventListener('click',async()=>{try{await api('logout',{});user=null;dialog.close();location.reload();}catch(err){status.textContent=tr(err.message);}});form.append(logout);}
else {const nav=el('div');for(const [value,text] of [['login','Sign in'],['register','Create account']]){const b=el('button',text);b.type='button';b.setAttribute('aria-pressed',String(mode===value));b.addEventListener('click',()=>{mode=value;open();});nav.append(b);}form.append(nav);for(const [name,label,type] of [...(mode==='register'?[['name','Name','text']]:[]),['email','Email','email'],['password','Password','password']]){const row=el('label',label),input=el('input');input.name=name;input.type=type;input.required=true;input.maxLength=name==='password'?128:name==='name'?100:254;input.autocomplete=name==='password'?(mode==='register'?'new-password':'current-password'):name;if(name==='password'&&mode==='register')input.minLength=10;row.append(input);form.append(row);}const submit=el('button',mode==='register'?'Create account':'Sign in');form.append(submit);form.addEventListener('submit',async e=>{e.preventDefault();submit.disabled=true;try{const data=Object.fromEntries(new FormData(form));user=(await api(mode,data)).user;dialog.close();location.reload();}catch(err){status.textContent=tr(err.message);submit.disabled=false;}});}
dialog.showModal();}
function install(){const birth=document.getElementById('quick-basic');if(birth&&!document.getElementById('quick-online-account')){const button=el('button');button.type='button';button.id='quick-online-account';button.className=birth.className;button.textContent='◉';button.title=tr('Account')+' · '+tr('Sign in');button.setAttribute('aria-label',button.title);birth.parentElement.append(button);} }
document.addEventListener('click',e=>{if(e.target.closest('#quick-online-account')){e.preventDefault();e.stopImmediatePropagation();open();}},true);
function init(){install();const host=document.getElementById('application');if(host)new MutationObserver(install).observe(host,{childList:true,subtree:true});if(hosted)api('me').then(d=>{user=d.user;if(location.hash==='#account')open();}).catch(()=>{});window.addEventListener('kp-preferences-changed',install);}
const style=el('style');style.textContent='.kp-account-dialog{width:330px;max-width:90vw;border:1px solid #b9cbdc;border-radius:9px;padding:18px;color:#203c54;background:#fff}.kp-account-dialog::backdrop{background:#15314d55}.kp-account-dialog h2{font-size:18px;margin:0 0 12px}.kp-account-dialog form{display:grid;gap:10px}.kp-account-dialog label{display:grid;gap:4px;font-size:13px}.kp-account-dialog input{padding:7px;min-width:0}.kp-account-dialog button{margin:2px;padding:6px 10px}.kp-account-dialog [role=status]{font-size:12px;color:#9b2a2a}';document.head.append(style);window.KPOnlineAccount=Object.freeze({open,install});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();})();
